// LoadAlertHistories loads the alertRule's AlertHistories into the .R struct
func (os AlertRuleSlice) LoadAlertHistories(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	alertHistories, err := os.AlertHistories(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AlertHistories = nil
		o.R.Loaded.AlertHistories = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	alertRuleByKey := make(map[string][]*AlertRule, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		alertRuleByKey[o.ID] = append(alertRuleByKey[o.ID], o)
	}

	for _, rel := range alertHistories {

		if !rel.AlertRuleID.IsValue() {
			continue
		}

		owners, ok := alertRuleByKey[rel.AlertRuleID.MustGet()]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.AlertRule = o
			rel.R.Loaded.AlertRule = true

			o.R.AlertHistories = append(o.R.AlertHistories, rel)

		}
	}

	return nil
}

