// alertRuleC is where relationship counts are stored.
type alertRuleC struct {
	AlertHistories *int64
	AlertStates    *int64
}

// PreloadCount sets a count in the C struct by name
func (o *AlertRule) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AlertHistories":
		o.C.AlertHistories = &count
	case "AlertStates":
		o.C.AlertStates = &count
	}
	return nil
}

type alertRuleCountPreloader struct {
	AlertHistories func(...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader
	AlertStates    func(...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader
}

func buildAlertRuleCountPreloader() alertRuleCountPreloader {
	return alertRuleCountPreloader{
		AlertHistories: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*AlertRule]("AlertHistories", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = AlertRules.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(AlertHistories.NameAsExpr()),
					sm.Where(sqlite.Quote(AlertHistories.Alias(), "alert_rule_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
		AlertStates: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*AlertRule]("AlertStates", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = AlertRules.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(AlertStates.NameAsExpr()),
					sm.Where(sqlite.Quote(AlertStates.Alias(), "alert_rule_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
	}
}

type alertRuleCountThenLoader[Q orm.Loadable] struct {
	AlertHistories func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AlertStates    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildAlertRuleCountThenLoader[Q orm.Loadable]() alertRuleCountThenLoader[Q] {
	type AlertHistoriesCountInterface interface {
		LoadCountAlertHistories(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AlertStatesCountInterface interface {
		LoadCountAlertStates(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return alertRuleCountThenLoader[Q]{
		AlertHistories: countThenLoadBuilder[Q](
			"AlertHistories",
			func(ctx context.Context, exec bob.Executor, retrieved AlertHistoriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAlertHistories(ctx, exec, mods...)
			},
		),
		AlertStates: countThenLoadBuilder[Q](
			"AlertStates",
			func(ctx context.Context, exec bob.Executor, retrieved AlertStatesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAlertStates(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountAlertHistories loads the count of AlertHistories into the C struct
