type alertRuleJoins[Q dialect.Joinable] struct {
	typ                 string
	AlertHistories      modAs[Q, alertHistoryColumns]
	NotificationChannel modAs[Q, notificationChannelColumns]
	Node                modAs[Q, nodeColumns]
	User                modAs[Q, userColumns]
	AlertStates         modAs[Q, alertStateColumns]
}

func (j alertRuleJoins[Q]) aliasedAs(alias string) alertRuleJoins[Q] {
	return buildAlertRuleJoins[Q](buildAlertRuleColumns(alias), j.typ)
}

func buildAlertRuleJoins[Q dialect.Joinable](cols alertRuleColumns, typ string) alertRuleJoins[Q] {
	return alertRuleJoins[Q]{
		typ: typ,
		AlertHistories: modAs[Q, alertHistoryColumns]{
			c: AlertHistories.Columns,
			f: func(to alertHistoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertHistories.NameExpr().As(to.Alias())).On(
						to.AlertRuleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		NotificationChannel: modAs[Q, notificationChannelColumns]{
			c: NotificationChannels.Columns,
			f: func(to notificationChannelColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, NotificationChannels.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.NotificationChannelID),
					))
				}

				return mods
			},
		},
		Node: modAs[Q, nodeColumns]{
			c: Nodes.Columns,
			f: func(to nodeColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Nodes.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.NodeID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
		AlertStates: modAs[Q, alertStateColumns]{
			c: AlertStates.Columns,
			f: func(to alertStateColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertStates.NameExpr().As(to.Alias())).On(
						to.AlertRuleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
